'use client'
import { cn, useSignal, useSignals } from '@cascivo/core'
import { builtin, t } from '@cascivo/i18n'
import type { HTMLAttributes, ReactNode } from 'react'
import styles from './alert.module.css'

export interface AlertProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'> {
  /**
   * Severity tone: `default` (neutral), `info`, `success`, `warning` or `destructive`. Sets
   * the icon and the accent colour. Unlike Badge/Tag/Notification this is a private union,
   * not `ToneInput` — the canonical `danger`/`neutral` spellings are not accepted here.
   *
   * @defaultValue `default`
   * @see the component manifest
   */
  variant?: 'default' | 'info' | 'success' | 'warning' | 'destructive'
  title?: string
  icon?: ReactNode
  /**
   * When true, shows a control to dismiss the component.
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  dismissible?: boolean
  onDismiss?: () => void
  action?: { label: string; onClick: () => void }
}

const assertiveVariants = new Set(['warning', 'destructive'])

export function Alert({
  variant = 'default',
  title,
  icon,
  dismissible = false,
  onDismiss,
  action,
  className,
  children,
  ...props
}: AlertProps) {
  useSignals()
  const dismissed = useSignal(false)
  if (dismissed.value) return null

  return (
    <div
      role={assertiveVariants.has(variant) ? 'alert' : 'status'}
      data-variant={variant}
      className={cn(styles['alert'], className)}
      {...props}
    >
      {icon && (
        <span className={styles['icon']} aria-hidden="true">
          {icon}
        </span>
      )}
      <div className={styles['body']}>
        {title && <div className={styles['title']}>{title}</div>}
        {children && <div className={styles['content']}>{children}</div>}
        {action && (
          <button type="button" className={styles['action']} onClick={action.onClick}>
            {action.label}
          </button>
        )}
      </div>
      {dismissible && (
        <button
          type="button"
          className={styles['dismiss']}
          aria-label={t(builtin.alert.dismiss)}
          onClick={() => {
            dismissed.value = true
            onDismiss?.()
          }}
        >
          ✕
        </button>
      )}
    </div>
  )
}

@layer cascivo.component {
  .alert {
    display: flex;
    gap: var(--cascivo-space-3);
    padding: var(--cascivo-space-4);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-surface);
    background-color: var(--cascivo-color-surface);
    font-family: var(--cascivo-font-sans);
    color: var(--cascivo-color-text);

    &[data-variant='info'] {
      border-color: color-mix(in oklch, var(--cascivo-color-info) 35%, var(--cascivo-color-border));
      background: color-mix(in oklch, var(--cascivo-color-info) 5%, var(--cascivo-color-bg));
      color: var(--cascivo-color-info-content);
    }

    &[data-variant='info'] .icon,
    &[data-variant='info'] .title {
      color: var(--cascivo-color-info-foreground, var(--cascivo-color-info));
    }

    &[data-variant='success'] {
      border-color: color-mix(
        in oklch,
        var(--cascivo-color-success) 35%,
        var(--cascivo-color-border)
      );
      background: color-mix(in oklch, var(--cascivo-color-success) 5%, var(--cascivo-color-bg));
      color: var(--cascivo-color-success-content);
    }

    &[data-variant='success'] .icon,
    &[data-variant='success'] .title {
      color: var(--cascivo-color-success-foreground, var(--cascivo-color-success));
    }

    &[data-variant='warning'] {
      border-color: color-mix(
        in oklch,
        var(--cascivo-color-warning) 35%,
        var(--cascivo-color-border)
      );
      background: color-mix(in oklch, var(--cascivo-color-warning) 5%, var(--cascivo-color-bg));
      color: var(--cascivo-color-warning-content);
    }

    &[data-variant='warning'] .icon,
    &[data-variant='warning'] .title {
      color: var(--cascivo-color-warning-foreground, var(--cascivo-color-warning));
    }

    &[data-variant='destructive'] {
      border-color: color-mix(
        in oklch,
        var(--cascivo-color-destructive) 35%,
        var(--cascivo-color-border)
      );
      background: color-mix(in oklch, var(--cascivo-color-destructive) 5%, var(--cascivo-color-bg));
      color: var(--cascivo-color-destructive-content);
    }

    &[data-variant='destructive'] .icon,
    &[data-variant='destructive'] .title {
      color: var(--cascivo-color-destructive-foreground, var(--cascivo-color-destructive));
    }
  }

  .icon {
    display: flex;
    flex-shrink: 0;
    align-items: center;
    line-height: 1;
    margin-block-start: 0.125rem;

    .alert[data-variant='info'] & {
      color: var(--cascivo-color-info-foreground, var(--cascivo-color-info));
    }
    .alert[data-variant='success'] & {
      color: var(--cascivo-color-success-foreground, var(--cascivo-color-success));
    }
    .alert[data-variant='warning'] & {
      color: var(--cascivo-color-warning-foreground, var(--cascivo-color-warning));
    }
    .alert[data-variant='destructive'] & {
      color: var(--cascivo-color-destructive-foreground, var(--cascivo-color-destructive));
    }
  }

  .body {
    display: flex;
    flex-direction: column;
    gap: var(--cascivo-space-1);
    flex: 1;
    min-inline-size: 0;
  }

  .title {
    font-size: var(--cascivo-text-sm);
    font-weight: var(--cascivo-font-semibold);
    line-height: var(--cascivo-leading-snug);
  }

  .content {
    font-size: var(--cascivo-text-sm);
    color: var(--cascivo-color-text-subtle);
    line-height: var(--cascivo-leading-normal);
  }

  .action {
    align-self: flex-start;
    margin-block-start: var(--cascivo-space-1);
    padding-block: var(--cascivo-space-1);
    padding-inline: var(--cascivo-space-2);
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-sm);
    font-weight: var(--cascivo-font-medium);
    line-height: var(--cascivo-leading-none);
    color: var(--cascivo-color-text);
    background: transparent;
    border: none;
    border-radius: var(--cascivo-radius-control);
    cursor: pointer;
    transition: background-color var(--cascivo-duration-150) var(--cascivo-ease-out);

    &:hover {
      background-color: var(--cascivo-color-bg-subtle);
    }

    &:focus-visible {
      outline: none;
      box-shadow: var(--cascivo-focus-ring);
    }

    .alert[data-variant='info'] & {
      color: var(--cascivo-color-info-foreground, var(--cascivo-color-info));
    }
    .alert[data-variant='success'] & {
      color: var(--cascivo-color-success-foreground, var(--cascivo-color-success));
    }
    .alert[data-variant='warning'] & {
      color: var(--cascivo-color-warning-foreground, var(--cascivo-color-warning));
    }
    .alert[data-variant='destructive'] & {
      color: var(--cascivo-color-destructive-foreground, var(--cascivo-color-destructive));
    }
  }

  .dismiss {
    display: flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    inline-size: 1.5rem;
    block-size: 1.5rem;
    padding: 0;
    font-size: var(--cascivo-text-xs);
    color: var(--cascivo-color-text-muted);
    background: transparent;
    border: none;
    border-radius: var(--cascivo-radius-control);
    cursor: pointer;
    transition:
      color var(--cascivo-duration-150) var(--cascivo-ease-out),
      background-color var(--cascivo-duration-150) var(--cascivo-ease-out);

    &:hover {
      color: var(--cascivo-color-text);
      background-color: var(--cascivo-color-bg-subtle);
    }

    &:focus-visible {
      outline: none;
      box-shadow: var(--cascivo-focus-ring);
    }
  }
}

@media (forced-colors: active) {
  .alert {
    border: 1px solid CanvasText;
  }

  .alert[data-variant='info'],
  .alert[data-variant='success'],
  .alert[data-variant='warning'],
  .alert[data-variant='destructive'] {
    border-width: 2px;
  }

  .dismiss:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: 2px;
  }
}

@media (prefers-contrast: more) {
  .alert {
    border-width: 2px;
  }

  .alert[data-variant='info'],
  .alert[data-variant='success'],
  .alert[data-variant='warning'],
  .alert[data-variant='destructive'] {
    border-width: 2px;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Alert',
  description: 'Highlights a short, important message inline',
  category: 'display',
  // The message renders in full; only the optional dismiss button needs JS.
  clientJs: 'enhancement',
  states: [],
  variants: ['default', 'info', 'success', 'warning', 'destructive'],
  sizes: [],
  props: [
    {
      name: 'variant',
      description:
        'Severity tone: `default` (neutral), `info`, `success`, `warning` or `destructive`. Sets the icon and the accent colour. Unlike Badge/Tag/Notification this is a private union, not `ToneInput` — the canonical `danger`/`neutral` spellings are not accepted here.',
      type: "'default' | 'info' | 'success' | 'warning' | 'destructive'",
      required: false,
      default: 'default',
    },
    {
      name: 'title',
      description: 'Title text for the component.',
      type: 'string',
      required: false,
    },
    {
      name: 'icon',
      description: 'Icon element rendered in the component.',
      type: 'ReactNode',
      required: false,
    },
    {
      name: 'dismissible',
      description: 'When true, shows a control to dismiss the component.',
      type: 'boolean',
      required: false,
      default: 'false',
    },
    {
      name: 'onDismiss',
      description: 'Called when the component is dismissed.',
      type: '() => void',
      required: false,
    },
    {
      name: 'action',
      description: 'Primary action shown in the component.',
      type: '{ label: string; onClick: () => void }',
      required: false,
    },
  ],
  tokens: [
    '--cascivo-color-info',
    '--cascivo-color-success',
    '--cascivo-color-warning',
    '--cascivo-color-destructive',
    '--cascivo-color-border',
    '--cascivo-radius-md',
  ],
  accessibility: {
    role: 'alert',
    wcag: '2.2-AA',
    keyboard: [],
    reducedMotion: true,
    forcedColors: true,
  },
  examples: [
    { title: 'Info', code: '<Alert variant="info" title="Heads up">Your trial ends soon.</Alert>' },
    {
      title: 'Dismissible',
      code: '<Alert variant="success" dismissible title="Saved">Changes saved.</Alert>',
    },
    {
      title: 'Actionable',
      code: '<Alert variant="warning" title="Update available" action={{ label: \'Update now\', onClick: update }}>A new version is ready.</Alert>',
    },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  tags: ['notification', 'message', 'feedback'],
  intent: {
    whenToUse: [
      'Surfacing a persistent, contextual message inline within a view (warning, error, info, success)',
      'Communicating status that should stay visible until read or resolved',
      'Offering an inline recovery action tied to the message (action prop)',
    ],
    whenNotToUse: [
      'Transient confirmation that should auto-dismiss — use Toast',
      'Blocking the user for a decision — use Modal or AlertDialog',
    ],
    antiPatterns: [
      {
        bad: 'Auto-dismissing an Alert on a timer to mimic a notification',
        good: '<Toast> for ephemeral feedback',
        why: 'Alerts persist by design; auto-hiding important inline context risks the user missing it',
      },
    ],
    related: [
      {
        name: 'Toast',
        relationship: 'alternative',
        reason: 'Toast auto-dismisses and floats; Alert persists inline in the layout',
      },
      {
        name: 'AlertDialog',
        relationship: 'alternative',
        reason: 'Use AlertDialog when the message must block and demand a choice',
      },
    ],
    a11yRationale:
      'role="alert" makes assistive tech announce the message when it appears; the dismiss control is a real button so it is reachable and labeled, and color is paired with an icon/title so meaning is not conveyed by hue alone',
    content: {
      tone: 'Direct and specific — state what happened and what to do next',
      notes: 'Title is a short summary; body explains. Avoid alarmist all-caps.',
    },
    flexibility: [
      {
        area: 'variant',
        level: 'flexible',
        note: 'Choose the severity variant that matches the message; default is neutral',
      },
      {
        area: 'token names',
        level: 'strict',
        note: 'Severity colors must resolve to --cascivo-color-info/success/warning/destructive',
      },
    ],
  },
}
